import{_ as s,o as e,c as n,a2 as o}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"启动模式：BIOS、UEFI 与 A/B 槽位菜单","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/boot-modes.md","filePath":"zh/manual/boot-modes.md"}'),t={name:"zh/manual/boot-modes.md"};function l(p,a,c,i,d,r){return e(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="启动模式-bios、uefi-与-a-b-槽位菜单" tabindex="-1">启动模式：BIOS、UEFI 与 A/B 槽位菜单 <a class="header-anchor" href="#启动模式-bios、uefi-与-a-b-槽位菜单" aria-label="Permalink to &quot;启动模式：BIOS、UEFI 与 A/B 槽位菜单&quot;">​</a></h1><h2 id="iso-是混合启动镜像" tabindex="-1">ISO 是混合启动镜像 <a class="header-anchor" href="#iso-是混合启动镜像" aria-label="Permalink to &quot;ISO 是混合启动镜像&quot;">​</a></h2><p><code>build/opencube.iso</code>（发布资源）包含两条启动路径：</p><ul><li><strong>Legacy BIOS</strong>：一个 El Torito 启动镜像（GRUB i386-pc，由 <code>tools/build_iso.sh</code> 通过 <code>grub-mkimage</code> + <code>xorriso</code> 构建）。</li><li><strong>UEFI</strong>：同一个 ISO 上的一个 EFI 启动镜像（<code>x86_64-efi</code>）。</li></ul><p>两条路径都加载相同的内核 ELF，并将内核自身作为标记为 <code>self</code> 的 multiboot2 模块附加 - 这是主流的安装程序模式：<code>install</code> 和 <code>abdisk</code> 命令将<em>当前正在运行的精确内核</em>复制到目标磁盘，因此已安装的系统始终与其安装程序匹配。</p><h2 id="grub-菜单" tabindex="-1">GRUB 菜单 <a class="header-anchor" href="#grub-菜单" aria-label="Permalink to &quot;GRUB 菜单&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>* Open Cube OS (slot ISO)</span></span>
<span class="line"><span>  Open Cube OS (slot A, force)</span></span>
<span class="line"><span>  Open Cube OS (slot B, force)</span></span></code></pre></div><ul><li><strong>slot ISO</strong> - 默认选项。从启动介质引导内核，并读取 A/B 启动标志以决定要链接哪个磁盘槽位（当标志不存在时回退到 ISO 内核）。</li><li><strong>slot A / slot B 强制</strong> - 忽略标志并直接引导该磁盘槽位。这是当糟糕的更新导致活动槽位无法启动时的恢复路径：从菜单中选择另一个槽位。</li></ul><p>菜单在 5 秒后自动引导高亮条目。</p><h2 id="grub-之后内核的操作" tabindex="-1">GRUB 之后内核的操作 <a class="header-anchor" href="#grub-之后内核的操作" aria-label="Permalink to &quot;GRUB 之后内核的操作&quot;">​</a></h2><p>启动顺序（这确实是串行日志）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>multiboot2 handshake OK</span></span>
<span class="line"><span>long mode entry OK</span></span>
<span class="line"><span>framebuffer 800x600x32 OK</span></span>
<span class="line"><span>console grid / 8x16 font engine OK</span></span>
<span class="line"><span>IDT + GDT + TSS (256 gates) OK</span></span>
<span class="line"><span>8259 PIC remap (IRQ0-15 -&gt; vec 32-47) OK</span></span>
<span class="line"><span>PIT @ 100 Hz + tick counter OK</span></span>
<span class="line"><span>PS/2 keyboard OK</span></span>
<span class="line"><span>COM1 serial RX OK</span></span>
<span class="line"><span>console input line editor OK</span></span>
<span class="line"><span>interrupts enabled (sti) OK</span></span>
<span class="line"><span>exception self-test: 3/3 (#DE/#UD/#PF) OK</span></span>
<span class="line"><span>PMM / VMM / heap OK</span></span>
<span class="line"><span>... drivers, VFS, network ...</span></span>
<span class="line"><span>shell command system (233 commands) OK</span></span>
<span class="line"><span>boot complete OK</span></span>
<span class="line"><span>crash recovery armed (panic + dump + crashlog) OK</span></span></code></pre></div><p>multiboot2 解析器（<code>kernel/arch/x86_64/arch_multiboot2.c</code>）读取 GRUB 从固件转发的帧缓冲标签、内存映射、命令行和 ACPI RSDP 标签（类型 14/15）- 在 UEFI 启动中 RSDP 通过此路径传递，在 BIOS 启动中 ACPI 驱动也可以扫描内存。</p><h2 id="启动参数" tabindex="-1">启动参数 <a class="header-anchor" href="#启动参数" aria-label="Permalink to &quot;启动参数&quot;">​</a></h2><p>GRUB 传递内核命令行；<code>grub.cfg</code> 使用它来传递 <code>BOOT_SLOT=ISO|A|B</code> 加上控制台偏好。在运行中的系统内部，<code>uname -a</code> 显示版本和构建信息，<code>abcfg</code> 打印 <code>abdisk</code>/<code>install</code> 生成的确切 grub.cfg 文件。</p><h2 id="持久化-etc-卷" tabindex="-1">持久化：/etc 卷 <a class="header-anchor" href="#持久化-etc-卷" aria-label="Permalink to &quot;持久化：/etc 卷&quot;">​</a></h2><p>系统查找要挂载到 <code>/etc</code> 的 FAT32 卷。当你引导普通 ISO 时不存在这样的卷-配置是临时的。<code>install</code> 在目标磁盘上创建一个（它包含 <code>opencube.conf</code>、SSH 主机密钥、<code>kernel.log*</code>、崩溃转储）。如果你只想获得持久性而不进行安装，请手动创建该卷：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; abdisk &lt;dev&gt;       (A/B disk with /etc volume - destroys data!)</span></span></code></pre></div><h2 id="引导真实硬件" tabindex="-1">引导真实硬件 <a class="header-anchor" href="#引导真实硬件" aria-label="Permalink to &quot;引导真实硬件&quot;">​</a></h2><p>将 ISO 写入 USB 闪存盘（<code>dd if=opencube.iso of=/dev/sdX</code> 或你喜欢的工具）。要求很简单：x86_64 CPU，512 MiB RAM。根据你的喜好通过 BIOS 或 UEFI 固件引导-两个镜像都在该闪存盘上。</p>`,20)])])}const b=s(t,[["render",l]]);export{u as __pageData,b as default};
